const fs=require('fs'),vm=require('vm'),assert=require('assert');
const code=fs.readFileSync('ground_truth_studio/bbox_canvas/index.html','utf8').split('<script>')[1].split('</script>')[0];
const messages=[],events={},context={clearRect(){},drawImage(){},strokeRect(){},fillText(){}};
const nodes={c:{getContext:()=>context,getBoundingClientRect(){return {left:0,top:0,width:this.width,height:this.height}},setPointerCapture(){}},cls:{value:'0'},remove:{},clear:{}};
class Image{constructor(){this.width=400;this.height=200}set src(v){this.onload()}}
const sandbox={document:{getElementById:id=>nodes[id]},parent:{postMessage:m=>messages.push(JSON.parse(JSON.stringify(m)))},window:{addEventListener:(k,fn)=>events[k]=fn},Image,console};
vm.createContext(sandbox);vm.runInContext(code,sandbox);
events.message({data:{type:'streamlit:render',args:{identity:'SYNTHETIC_ONLY',image:'synthetic',boxes:[]}}});
nodes.c.onpointerdown({clientX:40,clientY:20,pointerId:1});nodes.c.onpointerup({clientX:200,clientY:100});
let last=()=>messages.filter(m=>m.type==='streamlit:setComponentValue').at(-1).value;
assert.equal(last().boxes.length,1);assert.equal(last().identity,'SYNTHETIC_ONLY');assert(Math.abs(last().boxes[0].w-.4)<1e-12);
nodes.cls.value='1';nodes.cls.onchange();assert.equal(last().boxes[0].class_id,1);
nodes.remove.onclick();assert.equal(last().boxes.length,0);
nodes.c.onpointerdown({clientX:-40,clientY:-20,pointerId:1});nodes.c.onpointerup({clientX:500,clientY:300});
assert.equal(last().boxes[0].x,.5);assert.equal(last().boxes[0].w,1);
nodes.clear.onclick();assert.equal(last().boxes.length,0);
console.log('CANVAS_LOGIC_OK: synthetic draw, edit class, delete, clear, bounds clamp; no human approval submitted');
